insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-59'), 'published', 'Le mécanisme (taux de TVA, produits concernés) est précisément défini par la source. Deux chiffrages indépendants existent et divergent selon les hypothèses retenues sur la réaction de la consommation à la baisse de prix — ils sont présentés côte à côte plutôt que fondus en une moyenne. Aucun effet macroéconomique (emploi, PIB, inflation) n''a été estimé par une source publique identifiée à ce jour.', 'faisable_sous_conditions', 'precise', 'moyenne', 'loi_finances', false, false, 'Un changement de taux de TVA relève du domaine de la loi de finances (article 34 de la Constitution) et peut être voté en loi de finances initiale ou rectificative. La source ne précise aucune mesure de compensation de la perte de recettes.', 1, 12, 'oui', 'non', 'La DGFiP applique déjà des taux de TVA différenciés selon les produits ; un changement de taux ne nécessite pas de nouvelle structure administrative ni de recrutement identifié par la source.', '["Ménages consommant gaz, fioul ou électricité","Automobilistes"]'::jsonb, 'Concerne la quasi-totalité des ménages français, à des degrés très variables selon leur consommation d''énergie et de carburant.', null, null, null, null, null, 'lepen-tva-energie', '2026-09-04', 'Équipe éditoriale Poliscope', '2026-09-05') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-2'), 'published', 'Le volet « hausse du SMIC » est un mécanisme clair (revalorisation à un montant net cible), déjà modélisé par le Simulateur d''impact de Poliscope. Le volet « blocage des prix » n''est pas suffisamment défini par la source (produits concernés, durée, mécanisme de contrôle) pour être analysé séparément : cette fiche ne porte donc que sur la revalorisation du SMIC. Aucune source indépendante ne chiffre le coût budgétaire de cette mesure.', 'faisable_parametres_connus', 'partiellement_precis', 'moyenne', 'decret', false, false, 'Le montant du SMIC est fixé par décret pris en Conseil des ministres (article L3231-2 du code du travail), après avis de la Commission nationale de la négociation collective. Ce volet ne nécessite pas de loi.', 1, 3, 'oui', 'non', 'Le mécanisme de revalorisation du SMIC est un dispositif existant et récurrent (des revalorisations anticipées ont déjà été pratiquées par le passé).', '["Salariés rémunérés au SMIC"]'::jsonb, 'Salariés dont la rémunération nette est actuellement inférieure au seuil proposé de 1 600 €. Le chiffre ci-dessous porte sur les seuls salariés déjà au SMIC ; ceux situés entre le SMIC actuel et 1 600 € net ne sont pas comptabilisés, faute de source les isolant.', null, 2200000, null, 'DARES', 'https://dares.travail-emploi.gouv.fr/publication/combien-de-salaries-sont-remuneres-au-smic', 'melenchon-smic-1600', '2026-09-04', 'Équipe éditoriale Poliscope', '2026-09-05') on conflict (id) do nothing;
insert into measure_analyses (id, proposal_id, status, summary, feasibility_status, precision_level, confidence_level, legal_path, legal_constitutional_change_required, legal_eu_change_required, legal_notes, legal_implementation_delay_min_months, legal_implementation_delay_max_months, implementation_existing_administration, implementation_new_recruitment_needed, implementation_notes, beneficiaries_groups, beneficiaries_description, beneficiaries_count_min, beneficiaries_count_central, beneficiaries_count_max, beneficiaries_source_name, beneficiaries_source_url, simulator_measure_id, reviewed_at, reviewed_by, published_at) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:proposal:proposal-61'), 'published', 'Le mécanisme proposé (un référendum sur un texte encadrant l''immigration) soulève une question juridique documentée et non tranchée par le Conseil constitutionnel : l''article 11 de la Constitution, qui définit les sujets pouvant être soumis à référendum, ne mentionne pas explicitement la politique migratoire parmi les matières autorisées. Le contenu précis du texte qui serait soumis au vote (barème, critères, calendrier) n''est en outre pas détaillé par la source.', 'obstacle_juridique_majeur', 'insuffisant', 'moyenne', 'referendum', true, false, 'L''article 11 de la Constitution limite les sujets pouvant être soumis à référendum (organisation des pouvoirs publics, réformes relatives à la politique économique, sociale ou environnementale, ratification de traités) ; la politique migratoire n''y figure pas explicitement. Plusieurs constitutionnalistes cités par la source estiment qu''une révision constitutionnelle serait nécessaire au préalable. Ce point fait débat et n''a pas été tranché par une décision du Conseil constitutionnel à ce jour.', null, null, 'non_documente', 'non_documente', null, '[]'::jsonb, null, null, null, null, null, null, null, '2026-09-04', 'Équipe éditoriale Poliscope', '2026-09-05') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-1-budget-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'independent_body', 'Ministère de l''Économie et des Finances (chiffrage cité par Public Sénat)', 'https://www.publicsenat.fr/actualites/politique/baisse-de-la-tva-sur-lenergie-proposee-par-le-rn-une-mesure-chiffree-a-17-milliards-selon-bercy', 16.8, 16.8, 16.8, null, null, null, 'Md€', 2026, 'non', 'Détail du chiffrage : électricité 4,5 Md€ + gaz 2,3 Md€ + carburants 10 Md€ = 16,8 Md€. Couvre l''ensemble des postes visés par la mesure.') on conflict (id) do nothing;
insert into measure_budget_estimates (id, measure_analysis_id, source_type, source_name, source_url, annual_cost_min, annual_cost_central, annual_cost_max, annual_revenue_min, annual_revenue_central, annual_revenue_max, currency, reference_year, financing_identified, notes) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_budget_estimate:measure-analysis-1-budget-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'other', 'Institut Montaigne (think tank libéral)', 'https://www.institutmontaigne.org/legislatives-2024/rassemblement-national/baisser-la-tva-de-20-a-55-pour-les-carburants-lelectricite-le-gaz-et-le-fioul-domestique/', 9, 11.5, 14, null, null, null, 'Md€', 2024, 'non', 'Estimation republiée à l''occasion des législatives 2024 (une estimation antérieure du même institut, en 2022, chiffrait la mesure à 10 Md€/an). L''écart avec le chiffrage de Bercy tient notamment aux hypothèses retenues sur la réaction de la consommation à la baisse de prix.') on conflict (id) do nothing;
insert into measure_impacts (id, measure_analysis_id, impact_type, horizon, scenario, population, value_min, value_central, value_max, unit, confidence_level, method, source_name, source_url, scenario_assumptions, publication_date) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_impact:measure-analysis-1-impact-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'revenu_menages', 'court', 'unique', 'Ménage selon son profil de consommation d''énergie et de carburant', 7, 26, 41, '€/mois', 'moyenne', 'Calcul direct : application du nouveau taux de TVA à la dépense d''énergie et de carburant déclarée (voir Simulateur d''impact de Poliscope). Fourchette illustrative entre un profil faiblement et fortement consommateur ; ne prend pas en compte un éventuel effet sur les prix hors taxe.', null, null, null, '2026-09-04') on conflict (id) do nothing;
insert into measure_impacts (id, measure_analysis_id, impact_type, horizon, scenario, population, value_min, value_central, value_max, unit, confidence_level, method, source_name, source_url, scenario_assumptions, publication_date) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_impact:measure-analysis-2-impact-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-2'), 'revenu_menages', 'court', 'unique', 'Salarié actuellement rémunéré entre le SMIC et 1 600 € net', 50, null, 300, '€/mois', 'moyenne', 'Calcul direct : 1 600 € − salaire net actuel déclaré, pour les salariés rémunérés en dessous de ce seuil (voir Simulateur d''impact de Poliscope). Pas de scénario central pertinent : le gain dépend entièrement du salaire de départ.', null, null, null, '2026-09-04') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-1-assumption-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'Taux de TVA cible', '5,5', '%', 'candidate', 'Taux annoncé par la source pour l''électricité, le gaz, le fioul et les carburants.', 'CNEWS (amendement RN au budget 2026)', 'https://www.cnews.fr/france/2025-10-21/abaissement-de-la-tva-55-quels-produits-sont-concernes-par-lamendement-depose-par') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-1-assumption-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'Consommation de carburant (calcul individuel)', '6,5', 'L/100 km', 'manual_assumption', 'Hypothèse technique déjà utilisée par le Simulateur d''impact de Poliscope pour convertir un kilométrage annuel en dépense de carburant.', null, null) on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-1-assumption-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-1'), 'Délai de mise en œuvre législative', '1 à 12', 'mois', 'manual_assumption', 'Estimation Poliscope fondée sur le calendrier budgétaire français : une mesure de ce type peut être intégrée à une loi de finances rectificative en cours d''année, ou attendre la loi de finances initiale suivante.', null, null) on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-2-assumption-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-2'), 'Seuil de revalorisation du SMIC', '1 600', '€ net/mois', 'candidate', 'Montant annoncé par la source.', 'Programme « L''Avenir en commun » 2025 — chapitre 9', 'https://melenchon2027.fr/programme2025/livre/chapitre9/s1/') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-2-assumption-2'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-2'), 'Effectif des salariés au SMIC', '2,2', 'millions', 'official', 'Salariés ayant directement bénéficié de la revalorisation du SMIC au 1er novembre 2024, selon la DARES — sert de borne basse : les salariés situés entre le SMIC actuel et 1 600 € net s''y ajouteraient sans être chiffrés par une source identifiée.', 'DARES', 'https://dares.travail-emploi.gouv.fr/publication/combien-de-salaries-sont-remuneres-au-smic') on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-2-assumption-3'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-2'), 'Délai de mise en œuvre par décret', '1 à 3', 'mois', 'manual_assumption', 'Estimation Poliscope : un décret de revalorisation du SMIC peut être pris rapidement une fois la décision actée, sur le modèle des revalorisations anticipées déjà pratiquées.', null, null) on conflict (id) do nothing;
insert into measure_assumptions (id, measure_analysis_id, name, value, unit, assumption_type, justification, source_name, source_url) values (uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_assumption:measure-analysis-3-assumption-1'), uuid_generate_v5(uuid_ns_url(), 'poliscope:measure_analysis:measure-analysis-3'), 'Cadre constitutionnel applicable', 'Article 11', null, 'official', 'Texte constitutionnel définissant les matières pouvant être soumises à référendum.', 'Public Sénat', 'https://www.publicsenat.fr/actualites/politique/immigration-le-referendum-voulu-par-marine-le-pen-est-il-constitutionnel-190598') on conflict (id) do nothing;
